// Generates api/_knowledge.js (the AI receptionist's knowledge base) from src/data.js + src/media.json.
// Runs before every build. Do not edit api/_knowledge.js by hand.
import fs from 'node:fs'
import { mall, stores, restaurants, categories, events, faqs, BOT } from '../src/data.js'
const media = JSON.parse(fs.readFileSync(new URL('../src/media.json', import.meta.url), 'utf8'))
const clean = (t = '') => t.replace(/#[\wÀ-ÿ]+/g, '').replace(/\s*\/\s*/g, ' ').replace(/\s{2,}/g, ' ').trim()
const postsOf = (codes = []) => codes.map((c) => media.posts[c]).filter(Boolean).sort((a, b) => b.date.localeCompare(a.date))
const catName = (s) => categories.find((c) => c.slug === s)?.name || s
const L = []
L.push(`# ${mall.fullName}`, mall.description, `Dirección: ${mall.address}, ${mall.city}, ${mall.country}. Coordenadas ${mall.geo.lat}, ${mall.geo.lng}. Cómo llegar: ${mall.mapsUrl}`)
L.push(`Teléfono administración: ${mall.phone}. Instagram ${mall.socials.instagram.handle} (${mall.socials.instagram.followers} seguidores). Facebook: ${mall.socials.facebook.url}`)
L.push(`Horario general (zona horaria Bolivia, UTC-4): ${mall.hours.map((h) => `${h.days} ${h.open}-${h.close}`).join('; ')}. Cada local puede tener su propio horario.`)
L.push('No publicado / desconocido: correo electrónico oficial, WhatsApp de la administración, estacionamiento, cine, cantidad total de locales, metros cuadrados, año de apertura.')
L.push('', '# Páginas del sitio', '/ inicio (hero, categorías, tiendas destacadas, gastronomía, reels, agenda, experiencias, comunidad, visitanos)', '/tiendas directorio con filtros (?cat=moda, ?q=texto)', '/gastronomia restaurantes y cafés', '/ayuda preguntas frecuentes', '/legal/terminos, /legal/privacidad, /legal/cookies (no usamos cookies de seguimiento; solo una marca en almacenamiento local), /legal/aviso-legal, /legal/accesibilidad (objetivo WCAG 2.2 AA)', `Asistente: ${BOT.name} (IA, puede equivocarse, no guarda conversaciones en el sitio).`)
L.push('', '# Eventos y promociones (publicados por el mall)')
events.forEach((e) => L.push(`- ${e.title} (${e.when}): ${e.text}${e.link ? ` Bases: ${e.link}` : ''} [post ${media.posts[e.post]?.date || ''}]`))
L.push('', '# Restaurantes y cafés')
restaurants.forEach((r) => {
  L.push(`## ${r.name} — ${r.cuisine} — página /gastronomia/${r.slug} — Instagram ${r.ig ? '@' + r.ig : 'no publicado'}`)
  L.push(`Sobre: ${r.about} Para probar (según publicaciones, no es menú completo): ${r.menu.join(', ')}.`)
  L.push(r.wa ? `Reservas/WhatsApp: ${r.phone} (https://wa.me/${r.wa})` : 'Reservas: no publicó número; escribir por Instagram.')
  postsOf(r.posts).forEach((p) => L.push(`  Publicación ${p.date}: ${clean(p.caption).slice(0, 300)}`))
})
L.push('', '# Tiendas y servicios')
stores.forEach((s) => {
  L.push(`## ${s.name} — ${catName(s.cat)} — página /tiendas/${s.slug} — Instagram @${s.ig}`)
  L.push(`Sobre: ${s.about} Qué encontrás: ${s.lines.join(', ')}. Ubicación exacta dentro del centro: no publicada.`)
  postsOf(s.posts).forEach((p) => L.push(`  Publicación ${p.date}: ${clean(p.caption).slice(0, 300)}`))
})
L.push('', '# Otras publicaciones recientes del mall')
Object.values(media.posts).filter((p) => p.type === 2).sort((a, b) => b.date.localeCompare(a.date)).slice(0, 12).forEach((p) => L.push(`- ${p.date}: ${clean(p.caption).slice(0, 220)}`))
L.push('', '# Preguntas frecuentes'); faqs.forEach((f) => L.push(`P: ${f.q} R: ${f.a}`))
const text = L.join('\n')
fs.writeFileSync(new URL('../api/_knowledge.js', import.meta.url), `// GENERATED by scripts/build-knowledge.mjs — do not edit.\nexport const KNOWLEDGE = ${JSON.stringify(text)}\n`)
console.log(`knowledge: ${text.length} chars (~${Math.round(text.length / 3.5)} tokens)`)
